import{_ as r,o,c as a,a5 as e}from"./chunks/framework.B5tqjWbr.js";const _=JSON.parse('{"title":"PP-11 Boost PFC 与母线动态 - 知识检查","description":"","frontmatter":{"date":"2026-06-11T00:00:00.000Z","section":"电机控制","chapter":"power-path","chapterTitle":"功率链路","chapterOrder":40,"category":"功率链路","source":"motor","visibility":"public","title":"PP-11 Boost PFC 与母线动态 - 知识检查","tags":["motor-control"],"status":"learning","summary":"**模块编号：** PP-11 **题目数量：** 8 **验收目标：** 能解释 Boost PFC 的电流环、电压环、前馈、母线跌落和负载阶跃，并能把母线动态映射到 lxfoc 的电压限幅和保护策略。","navGroup":"基础与硬件","navGroupOrder":20},"headers":[],"relativePath":"content/motor/power-path/PP-11-assessment.md","filePath":"content/motor/power-path/PP-11-assessment.md","lastUpdated":1783096495000}'),s={name:"content/motor/power-path/PP-11-assessment.md"};function d(n,t,l,h,i,c){return o(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="pp-11-boost-pfc-与母线动态-知识检查" tabindex="-1">PP-11 Boost PFC 与母线动态 - 知识检查 <a class="header-anchor" href="#pp-11-boost-pfc-与母线动态-知识检查" aria-label="Permalink to &quot;PP-11 Boost PFC 与母线动态 - 知识检查&quot;">​</a></h1><p><strong>模块编号：</strong> PP-11<br><strong>题目数量：</strong> 8<br><strong>验收目标：</strong> 能解释 Boost PFC 的电流环、电压环、前馈、母线跌落和负载阶跃，并能把母线动态映射到 lxfoc 的电压限幅和保护策略。</p><hr><h2 id="_1-双环结构" tabindex="-1">1. 双环结构 <a class="header-anchor" href="#_1-双环结构" aria-label="Permalink to &quot;1. 双环结构&quot;">​</a></h2><p><strong>问题：</strong> Boost PFC 为什么通常采用电压外环、电流内环？</p><p><strong>答案：</strong> 电压外环维持直流母线平均值，电流内环快速整形输入电流，使其跟随整流电压参考，从而实现高功率因数和低 THD。</p><hr><h2 id="_2-电压环带宽" tabindex="-1">2. 电压环带宽 <a class="header-anchor" href="#_2-电压环带宽" aria-label="Permalink to &quot;2. 电压环带宽&quot;">​</a></h2><p><strong>问题：</strong> PFC 电压环为什么不能设置得过快？</p><p><strong>参考答案：</strong> 电压环过快会把二倍工频母线纹波传递到电流参考，使输入电流畸变，降低 PF 并提高 THD。</p><hr><h2 id="_3-前馈作用" tabindex="-1">3. 前馈作用 <a class="header-anchor" href="#_3-前馈作用" aria-label="Permalink to &quot;3. 前馈作用&quot;">​</a></h2><p><strong>问题：</strong> 输入电压前馈的作用是什么？</p><p><strong>答案：</strong> 补偿输入电压变化对功率级增益的影响，使电流环在宽输入范围内保持相近动态性能。</p><hr><h2 id="_4-母线跌落对-lxfoc-的影响" tabindex="-1">4. 母线跌落对 lxfoc 的影响 <a class="header-anchor" href="#_4-母线跌落对-lxfoc-的影响" aria-label="Permalink to &quot;4. 母线跌落对 lxfoc 的影响&quot;">​</a></h2><p><strong>问题：</strong> 当 <code>vbus</code> 从 48 V 跌落到 36 V，FOC 电流环首先需要避免什么问题？</p><p>A. 机械摩擦增大<br> B. duty 越界和电压指令积分饱和<br> C. 编码器分辨率提高<br> D. 电机极对数变化</p><p><strong>答案：</strong> B</p><hr><h2 id="_5-仿真任务" tabindex="-1">5. 仿真任务 <a class="header-anchor" href="#_5-仿真任务" aria-label="Permalink to &quot;5. 仿真任务&quot;">​</a></h2><p><strong>任务：</strong> 设置 50% 负载阶跃并记录母线、电流指令和 lxfoc 电压限幅状态。</p><p><strong>验收标准：</strong></p><div class="kb-table-scroll"><table><thead><tr><th>指标</th><th>阈值</th></tr></thead><tbody><tr><td>母线最低值</td><td>不低于 <code>vbus_min</code></td></tr><tr><td>duty 合法性</td><td>100% 在 <code>[0, 1]</code></td></tr><tr><td>电流环保护</td><td>无误触发；若触发必须能解释原因</td></tr><tr><td>稳态恢复</td><td>母线在设定时间内回到 ±5%</td></tr></tbody></table></div><hr><h2 id="_6-纹波识别" tabindex="-1">6. 纹波识别 <a class="header-anchor" href="#_6-纹波识别" aria-label="Permalink to &quot;6. 纹波识别&quot;">​</a></h2><p><strong>问题：</strong> 单相 Boost PFC 母线二倍工频纹波如何影响电机驱动？</p><p><strong>参考答案：</strong> 纹波会周期性改变可用电压裕量，引起电流环限幅边界变化，严重时导致转矩脉动、弱磁抖动或欠压保护误触发。</p><hr><h2 id="_7-调试顺序" tabindex="-1">7. 调试顺序 <a class="header-anchor" href="#_7-调试顺序" aria-label="Permalink to &quot;7. 调试顺序&quot;">​</a></h2><p><strong>问题：</strong> PFC 前级和电机逆变后级联合调试时，推荐顺序是什么？</p><p><strong>答案：</strong> 先空载验证 PFC 母线闭环，再带假负载验证负载阶跃，随后接入逆变器低压限功率运行，最后开放电机动态负载。每一步都必须记录 <code>vbus</code>、输入电流、fault 和 duty。</p><hr><h2 id="_8-数据回传" tabindex="-1">8. 数据回传 <a class="header-anchor" href="#_8-数据回传" aria-label="Permalink to &quot;8. 数据回传&quot;">​</a></h2><p><strong>任务：</strong> 给出 PP-11 对 lxfoc trace 的最小字段要求。</p><p><strong>参考答案：</strong> <code>time_s, iq_A, iq_ref_A, ud_V, uq_V, duty_a, duty_b, duty_c, vbus_V, speed_hz, fault_flags</code>。若做三相平衡，还应包含 <code>ia_A, ib_A, ic_A</code>。</p><hr><h2 id="评分" tabindex="-1">评分 <a class="header-anchor" href="#评分" aria-label="Permalink to &quot;评分&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th style="text-align:right;">得分</th><th>评价</th></tr></thead><tbody><tr><td style="text-align:right;">7-8</td><td>可进行 PFC-电机联合仿真和低压台架验证</td></tr><tr><td style="text-align:right;">5-6</td><td>需要补充母线动态与 FOC 限幅</td></tr><tr><td style="text-align:right;">&lt;5</td><td>需要重学 Boost PFC 基础</td></tr></tbody></table></div>',39)])])}const g=r(s,[["render",d]]);export{_ as __pageData,g as default};
